%[text]{"align":"center"} $\\frac{dT}{dt} = \\alpha \\frac{d^2T}{dx^2}$
% Discretize the domain
n = 2000;
x = linspace(0,0.1,n)';
dx = x(2) - x(1);
dt = 0.0000000000002;
alpha = 100;
r = alpha*dt/dx^2 %[output:945ab39c]
1 
%%

% Create the initial condition
T = 0*x; % degC

% Apply boundary condition
T(1) = 0;
T(end) = 20;
plot(x,T) %[output:7df37e52]

%[text] T(0) = 0 and T(1) = 20
%[text]{"align":"center"} $\\frac{T\_{i+1}-T\_{i} }{\\Delta t} = \\alpha \\frac{d^2T}{dx^2}$
%[text]{"align":"center"} $T\_{i+1}-T\_{i}   =  \\Delta t\\times \\alpha \\frac{d^2T}{dx^2}$
%[text]{"align":"center"} $T\_{i+1}   = T\_i +   \\Delta t\\times \\alpha \\frac{d^2T}{dx^2} \\\\\n\nT\_{i+1}   = T\_i +   \\Delta T \\\\\n\n\\Delta T = \\Delta t\\times \\alpha \\frac{d^2T}{dx^2} $
%[text]{"align":"center"}  $\\frac{d^2T}{dx^2} = \\frac{T\_{j-1} - 2T\_{j} + T\_{j+1}} {\\Delta x^2}= A\\times T$
%[text]{"align":"center"} 
% Find a way to compute \Delta T
A = zeros(n) %[output:84438e23]
for ii = 2:n-1
    A(ii,ii) = -2/dx^2;
    A(ii,ii-1) = 1/dx^2;
    A(ii,ii+1) = 1/dx^2;
end

for nt = 1:1000
    % Apply boundary condition
    T(1) = 0;
    T(end) = 20;
    T = T + dt * alpha * A * T;
end
DeltaT %[output:9128c7bb]
hold on %[output:7df37e52]
plot(x,T) %[output:7df37e52]
hold off %[output:7df37e52]
%%
